'use strict';

// MODULES //

var isSymbolShorthand = require( '@stdlib/plot/base/assert/is-symbol-shorthand' );
var isSymbolAlias = require( '@stdlib/plot/base/assert/is-symbol-alias' );


// MAIN //

/**
* Tests whether an input value is a supported symbol.
*
* ## Notes
*
* -   A symbol is either a symbol alias or a symbol shorthand.
*
* @param {*} v - value to test
* @returns {boolean} boolean indicating whether an input value is a supported symbol
*
* @example
* var bool = isSymbol( 'circle' );
* // returns true
*
* bool = isSymbol( 'o' );
* // returns true
*
* bool = isSymbol( 'foo' );
* // returns false
*
* bool = isSymbol( '' );
* // returns false
*/
function isSymbol( v ) {
	return ( isSymbolAlias( v ) || isSymbolShorthand( v ) );
}


// EXPORTS //

module.exports = isSymbol;
